<script setup lang="ts">
import {localize} from './localization';

import {interiorAnchor} from '../../../packages/pattern/interior';
import {computed,ref,watch} from 'vue';
import {useSession} from './store';
import {alignmentOffset,type Alignment} from '../../../packages/pattern/corners';
import {splitEdge,mapPiece} from '../../../packages/pattern/edit';
import type {Piece,Point} from '../../../packages/schema/index';
const props=defineProps<{piece:Piece;nodeId:string;language:'zh'|'en'}>();
const emit=defineEmits<{select:[id:string];hole:[]}>();const store=useSession();
const zh=computed(()=>props.language==='zh'),node=computed(()=>props.piece.nodes.find(n=>n.id===props.nodeId)??props.piece.nodes[0]);
const edge=computed(()=>{const i=props.piece.nodes.findIndex(n=>n.id===node.value.id);return {a:node.value,b:props.piece.nodes[(i+1)%props.piece.nodes.length]};});
const hasEdge=computed(()=>props.piece.closed||props.piece.nodes.at(-1)?.id!==node.value.id);
const trimEnd=ref(''),reverseA=ref(false),reverseB=ref(false);
async function trim(){const p=store.data.project;if(p&&trimEnd.value)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'piece.trim',pieceId:props.piece.id,startId:node.value.id,endId:trimEnd.value}));}
async function join(){const p=store.data.project;if(p&&otherId.value)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'piece.join',a:props.piece.id,b:otherId.value,reverseA:reverseA.value,reverseB:reverseB.value}));}
async function closePath(){if(props.piece.nodes.length<3){store.error='PATH_MIN_NODES';return;}await put({...props.piece,closed:true});}
const cornerKind=ref<'round'|'bevel'>('round'),cornerSize=ref(10),alignment=ref<Alignment>('left');
async function corner(){const p=store.data.project;if(p)await store.run(()=>window.fpcad.corner(p.id,p.revision,props.piece.id,node.value.id,cornerKind.value,cornerSize.value));}
async function align(){const p=store.data.project,target=p?.pieces.find(p=>p.id===otherId.value);if(!p||!target)return;const outline=(piece:Piece)=>{const nodes=store.data.geometry.find(g=>g.id===piece.id)?.seam;return nodes?.length?nodes:piece.nodes;};const delta=alignmentOffset(outline(props.piece),outline(target),alignment.value);await put(mapPiece(props.piece,n=>({xMm:n.xMm+delta.xMm,yMm:n.yMm+delta.yMm})));}
const moveX=ref(0),moveY=ref(0),angleDegrees=ref(0);
const c1x=ref(0),c1y=ref(0),c2x=ref(0),c2y=ref(0),notchPosition=ref(.5),notchDepth=ref(3),notchLabel=ref('1'),text=ref(''),labelX=ref(0),labelY=ref(0),otherId=ref(''),operation=ref<'union'|'difference'|'intersection'|'xor'>('union');
watch(()=>JSON.stringify([props.piece.id,edge.value,props.piece.curves?.find(c=>c.startNodeId===edge.value.a.id)]),()=>{const {a,b}=edge.value;const curve=props.piece.curves?.find(c=>c.startNodeId===a.id);c1x.value=curve?.c1.xMm??a.xMm+(b.xMm-a.xMm)/3;c1y.value=curve?.c1.yMm??a.yMm+(b.yMm-a.yMm)/3;c2x.value=curve?.c2.xMm??a.xMm+2*(b.xMm-a.xMm)/3;c2y.value=curve?.c2.yMm??a.yMm+2*(b.yMm-a.yMm)/3;const anchor=interiorAnchor(props.piece.nodes,props.piece.holes);labelX.value=anchor.xMm;labelY.value=anchor.yMm;},{immediate:true});
async function put(piece:Piece){const p=store.data.project;if(p)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'piece.put',piece:JSON.parse(JSON.stringify(piece))}));}
const point=(xMm:number,yMm:number):Point=>({id:crypto.randomUUID(),xMm,yMm});
async function transform(){const p=props.piece,angle=angleDegrees.value*Math.PI/180,c=Math.cos(angle),s=Math.sin(angle),cx=p.nodes.reduce((a,n)=>a+n.xMm,0)/p.nodes.length,cy=p.nodes.reduce((a,n)=>a+n.yMm,0)/p.nodes.length;await put({...mapPiece(p,n=>({xMm:cx+(n.xMm-cx)*c-(n.yMm-cy)*s+moveX.value,yMm:cy+(n.xMm-cx)*s+(n.yMm-cy)*c+moveY.value})),furRad:p.furRad+angle,grainRad:p.grainRad===undefined?undefined:p.grainRad+angle});}
async function curve(remove=false){if(!hasEdge.value)return;const {a,b}=edge.value;const curves=(props.piece.curves??[]).filter(c=>c.startNodeId!==a.id);if(!remove)curves.push({id:crypto.randomUUID(),startNodeId:a.id,endNodeId:b.id,c1:point(c1x.value,c1y.value),c2:point(c2x.value,c2y.value)});await put({...props.piece,curves});}
async function insertNode(){if(!hasEdge.value)return;const p=store.data.project;if(p)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'piece.split',pieceId:props.piece.id,nodeId:edge.value.a.id,t:.5}));}
async function removeNode(){const {a}=edge.value;if(props.piece.nodes.length<=(props.piece.closed?3:2))return;const prev=props.piece.nodes[(props.piece.nodes.findIndex(n=>n.id===a.id)+props.piece.nodes.length-1)%props.piece.nodes.length];await put({...props.piece,nodes:props.piece.nodes.filter(n=>n.id!==a.id),curves:(props.piece.curves??[]).filter(c=>c.startNodeId!==a.id&&c.endNodeId!==a.id),notches:(props.piece.notches??[]).filter(n=>n.nodeId!==a.id&&n.nodeId!==prev.id),edgeAllowances:(props.piece.edgeAllowances??[]).filter(e=>e.nodeId!==a.id&&e.nodeId!==prev.id)});}
async function removeHole(i:number){const ids=new Set(props.piece.holes?.[i].map(n=>n.id));await put({...props.piece,holes:props.piece.holes?.filter((_,j)=>j!==i),edgeAllowances:props.piece.edgeAllowances?.filter(e=>!ids.has(e.nodeId))});}
async function notch(){if(!hasEdge.value)return;await put({...props.piece,notches:[...(props.piece.notches??[]),{id:crypto.randomUUID(),nodeId:node.value.id,position:notchPosition.value,depthMm:notchDepth.value,label:notchLabel.value}]});}
async function label(){if(!text.value.trim())return;await put({...props.piece,labels:[...(props.piece.labels??[]),{id:crypto.randomUUID(),xMm:labelX.value,yMm:labelY.value,text:text.value}]});}
async function boolean(){const p=store.data.project;if(!p||!otherId.value)return;if(await store.run(()=>window.fpcad.boolean(p.id,p.revision,props.piece.id,otherId.value,operation.value)))emit('select',store.data.project?.pieces.at(-1)?.id??'');}
</script>
<template>
 <div class="advanced-tools"><details><summary>{{zh?'圆角、倒角与对齐':localize('Fillet, bevel & alignment')}}</summary><p>{{zh?'作用于所选外环节点；已有曲线、剪口、逐边缝份或接缝占用相邻边时，先解除关联。几何改动会使旧展开绑定失效。':localize('Edits the selected outer node. Detach adjacent curves, notches, edge allowances or seams first. Contour changes invalidate old bindings.')}}</p><div class="two-col"><label>{{zh?'角点类型':localize('Corner type')}}<select v-model="cornerKind"><option value="round">{{zh?'圆角':localize('Fillet')}}</option><option value="bevel">{{zh?'倒角':localize('Bevel')}}</option></select></label><label>{{zh?'半径 / 边上距离 mm':localize('Radius / edge distance mm')}}<input v-model.number="cornerSize" type="number" min=".01" max="1000" step=".5"></label></div><button :disabled="store.busy" @click="corner">{{zh?'应用角点修改':localize('Apply corner edit')}}</button><label>{{zh?'对齐参考裁片':localize('Align to pattern')}}<select v-model="otherId"><option value="">—</option><option v-for="p in store.data.project?.pieces.filter(p=>p.id!==piece.id)" :key="p.id" :value="p.id">{{p.name}}</option></select></label><select v-model="alignment"><option v-for="(key,i) in (['left','centerX','right','bottom','centerY','top'] as const)" :key="key" :value="key">{{zh?['左对齐','水平居中','右对齐','底部对齐','垂直居中','顶部对齐'][i]:key}}</option></select><button :disabled="store.busy||!otherId" @click="align">{{zh?'按缝线轮廓对齐':localize('Align seam contours')}}</button></details><details><summary>{{zh?'路径修剪与连接':localize('Trim and join paths')}}</summary><p>{{zh?'从当前节点沿路径保留到结束节点；开放路径会阻止制造导出。连接端点须在 0.01 mm 内，材料与制造参数须一致。':localize('Keep the path from the current node through the end node. Open paths block manufacturing export. Join endpoints within 0.01 mm with matching material and manufacturing metadata.')}}</p><select v-model="trimEnd"><option value="">—</option><option v-for="(n,i) in piece.nodes" :key="n.id" :value="n.id">{{i+1}}</option></select><button :disabled="store.busy||!trimEnd" @click="trim">{{zh?'保留选定路径':localize('Trim to selected path')}}</button><button v-if="!piece.closed" :disabled="store.busy" @click="closePath">{{zh?'闭合路径':localize('Close path')}}</button><select v-model="otherId"><option value="">—</option><option v-for="p in store.data.project?.pieces.filter(p=>p.id!==piece.id&&!p.closed)" :key="p.id" :value="p.id">{{p.name}}</option></select><label><input v-model="reverseA" type="checkbox">{{zh?'反转当前路径':localize('Reverse current path')}}</label><label><input v-model="reverseB" type="checkbox">{{zh?'反转第二路径':localize('Reverse second path')}}</label><button :disabled="store.busy||piece.closed||!otherId" @click="join">{{zh?'连接路径':localize('Join paths')}}</button></details><details><summary>{{zh?'精确移动与任意角旋转':localize('Precise translation and rotation')}}</summary><div class="two-col"><label>ΔX mm<input v-model.number="moveX" type="number" step=".1"></label><label>ΔY mm<input v-model.number="moveY" type="number" step=".1"></label></div><label>{{zh?'旋转角度 °':localize('Rotation °')}}<input v-model.number="angleDegrees" type="number" step=".1"></label><button :disabled="store.busy" @click="transform">{{zh?'应用变换':localize('Apply transform')}}</button></details>
  <details><summary>{{zh?'轮廓、孔洞与布尔运算':localize('Contours, holes and boolean operations')}}</summary>
   <button :disabled="store.busy" @click="emit('hole')">{{zh?'绘制孔洞轮廓':localize('Draw a hole')}}</button>
   <div v-for="(_,i) in piece.holes??[]" :key="i" class="two-col"><span>{{zh?'孔洞':localize('Hole')}} {{i+1}}</span><button :disabled="store.busy" @click="removeHole(i)">×</button></div>
   <label>{{zh?'第二块纸样':localize('Second piece')}}<select v-model="otherId"><option value="">—</option><option v-for="p in store.data.project?.pieces.filter(p=>p.id!==piece.id)" :key="p.id" :value="p.id">{{p.name}}</option></select></label>
   <select v-model="operation"><option value="union">{{zh?'合并':localize('Union')}}</option><option value="difference">{{zh?'差集（从当前纸样减去第二块）':localize('Difference (current minus second)')}}</option><option value="intersection">{{zh?'交集':localize('Intersection')}}</option><option value="xor">{{zh?'异或':localize('XOR')}}</option></select>
   <small>{{zh?'结果替换两块源纸样，可撤销；拓扑变更会清除剪口和文字。':localize('Results replace both sources; undo restores them. Topology changes clear notches and labels.')}}</small>
   <button :disabled="!otherId||store.busy" @click="boolean">{{zh?'应用布尔运算':localize('Apply boolean operation')}}</button>
  </details>
  <details><summary>{{zh?'节点与三次 Bézier':localize('Nodes and cubic Bézier')}}</summary><small>{{zh?'编辑所选节点到下一节点的边；未选节点时使用第一条边。':localize('Edits selected node → next node; first edge when no node selected.')}}</small>
   <div class="two-col"><button :disabled="store.busy||!hasEdge" @click="insertNode">{{zh?'插入中点':localize('Insert midpoint')}}</button><button :disabled="store.busy||piece.nodes.length<=(piece.closed?3:2)" @click="removeNode">{{zh?'删除节点':localize('Delete node')}}</button></div>
   <div class="two-col"><label>C1 X<input v-model.number="c1x" type="number" step=".1"></label><label>C1 Y<input v-model.number="c1y" type="number" step=".1"></label><label>C2 X<input v-model.number="c2x" type="number" step=".1"></label><label>C2 Y<input v-model.number="c2y" type="number" step=".1"></label></div>
   <div class="two-col"><button :disabled="store.busy||!hasEdge" @click="curve()">{{zh?'应用曲线':localize('Apply curve')}}</button><button :disabled="store.busy||!hasEdge" @click="curve(true)">{{zh?'还原直线':localize('Restore line')}}</button></div>
  </details>
  <details><summary>{{zh?'对位剪口与文字标注':localize('Notches and labels')}}</summary>
   <label>{{zh?'边上位置（0–1）':localize('Edge position (0–1)')}}<input v-model.number="notchPosition" type="number" min="0" max="1" step=".05"></label>
   <div class="two-col"><label>{{zh?'剪口深度 mm':localize('Notch depth mm')}}<input v-model.number="notchDepth" type="number" min=".1" step=".1"></label><label>{{zh?'编号':localize('Number')}}<input v-model="notchLabel" maxlength="40"></label></div>
   <button :disabled="store.busy||!hasEdge" @click="notch">{{zh?'在所选边按弧长添加剪口':localize('Add arc-length notch to selected edge')}}</button>
   <button v-for="n in piece.notches??[]" :key="n.id" :disabled="store.busy" @click="put({...piece,notches:piece.notches?.filter(v=>v.id!==n.id)})">{{zh?'删除剪口':localize('Remove notch')}} {{n.label}} ×</button>
   <label>{{zh?'文字':localize('Text')}}<input v-model="text" maxlength="120"></label><div class="two-col"><label>X mm<input v-model.number="labelX" type="number"></label><label>Y mm<input v-model.number="labelY" type="number"></label></div><button :disabled="store.busy||!text.trim()" @click="label">{{zh?'添加标注':localize('Add label')}}</button>
   <button v-for="l in piece.labels??[]" :key="l.id" :disabled="store.busy" @click="put({...piece,labels:piece.labels?.filter(v=>v.id!==l.id)})">{{l.text}} ×</button>
  </details>
 </div>
</template>
<style scoped>.advanced-tools{border-top:1px solid var(--border);padding-top:12px}.advanced-tools details{margin:12px 0}.advanced-tools summary{cursor:pointer;font-size:12px;font-weight:600;margin-bottom:12px}.advanced-tools small{display:block;margin:8px 0;line-height:1.5}.advanced-tools button,.advanced-tools select{width:100%;margin:4px 0}.advanced-tools .two-col button{width:auto}</style>
